fn arccosh(x: Vec<f32>) -> Vec<f32> {
    // We assume the input is non-empty, as specified.
    let len = x.len();
    assert!(len > 0, "Input vector must be non-empty");

    // Pre‐allocate an output vector of the same length.
    let mut result = Vec::with_capacity(len);

    // Process each element by index, from 0 up to len−1.
    let mut idx = 0;
    while idx < len {
        let xi = x[idx];
        // arccosh(x) = ln( x + sqrt(x² − 1) )
        let yi = (xi + (xi * xi - 1.0).sqrt()).ln();
        result.push(yi);
        idx += 1;
    }

    result
}

