    // A simple helper: compute arccosh with high precision for comparison.
    fn reference_arccosh(x: f64) -> f64 {
        (x + (x * x - 1.0).sqrt()).ln()
    }

    #[test]
    fn test_arccosh_small() {
        let input = vec![1.0_f32, 1.5_f32, 2.0_f32, 3.0_f32];
        let out = arccosh(input.clone());
        for (i, &xi) in input.iter().enumerate() {
            let expected = reference_arccosh(xi as f64) as f32;
            let got = out[i];
            let diff = (got - expected).abs();
            assert!(diff < 1e-6, "at index {}: got {}, expected {}", i, got, expected);
        }
    }

